\section{LQ Lagrangian}
\label{sec:LQLagrangian}
The five possible scalar LQ representations $\Phi_1, \Phi_{\tilde{1}}, \Phi_2, \Phi_{\tilde{2}}, \Phi_3$ transform under the $SU(3)_c \times SU(2)_L \times U(1)_Y$ gauge group as~\cite{Buchmuller:1986zs} 


\begin{equation}
\renewcommand{\arraystretch}{1.1}
    \centering
    \begin{tabular}{c | c c c c c}
         & $\Phi_1,$ & $\Phi_{\tilde{1}}$ & $\Phi_2$ & $ \Phi_{\tilde{2}}$ & $\Phi_3$\\ \hline
    	$SU(3)_c$ & 3 & 3 & 3 & 3 & 3 \\
    	$SU(2)_L$ & 1 & 1 & 2 & 2 & 3 \\
    	$U(1)_Y$ & $-\frac{1}{3}$ & $-\frac{4}{3}$ & $\frac{7}{6}$ & $\frac{1}{6}$ & $-\frac{1}{3}$
    \end{tabular}\,.
\end{equation}


Note that we adopt the convention that all scalar LQs transform in the fundamental $SU(3)_c$ representation. Expanding the $SU(2)_L$ multiplets into their components, the following electric charge eigenstates are found


\renewcommand{\arraystretch}{1.5}
\begin{align}
    \begin{aligned}
        \Phi_1 = \left( \Phi_1^{-1/3}\right), \ 
        \Phi_{\tilde{1}} = \left( \Phi_{\tilde{1}}^{-4/3}\right), \ 
        \Phi_2 = \begin{pmatrix} \Phi^{+5/3}_2 \\ \Phi^{+2/3}_2 \end{pmatrix},\ \\
        \renewcommand{\arraystretch}{1.5}
        \Phi_{\tilde{2}} = \begin{pmatrix} \Phi^{+2/3}_{\tilde{2}} \\ \Phi^{-1/3}_{\tilde{2}} \end{pmatrix},\ 
        \sigma \cdot \Phi_{3} = \begin{pmatrix}
            \Phi_3^{-1/3} & \sqrt{2} \Phi_3^{+2/3} \\
            \sqrt{2} \Phi_3^{-4/3} & -\Phi_3^{-1/3}
        \end{pmatrix}\,. 
    \end{aligned}
\end{align}


We decompose the scalar LQ Lagrangian as


\begin{equation}
    \mathcal{L}^{\text{LQ}} = \mathcal{L}_{2 \Phi} + \mathcal{L}_{\text{kin}} +
    \mathcal{L}_{\text{f}}  + \mathcal{L}_{3 \Phi} + \mathcal{L}_{4 \Phi} \,,
\end{equation}


where $\mathcal{L}_{2 \Phi}$ contains the LQ masses and the LQ-LQ-Higgs(-Higgs) couplings, $\mathcal{L}_{\text{kin}}$  the kinetic terms and the couplings to the SM gauge bosons, $\mathcal{L}_{\text{f}}$ the couplings to the SM fermions, $\mathcal{L}_{3 \Phi}$ the LQ-LQ-LQ(-Higgs) couplings and finally $\mathcal{L}_{4 \Phi}$ the LQ-LQ-LQ-LQ interaction terms. The individual parts of the Lagrangians are discussed in more detail below. 



\subsection{LQ Masses and Higgs Interactions ($\mathcal{L}_{2 \Phi}$)}
\label{sec:LQ-Higgs}
The LQ masses and the LQ-LQ-Higgs(-Higgs) interactions are implemented by the Lagrangian \cite{Crivellin:2020ukd, Hirsch:1996qy}


\begin{equation}
    \begin{aligned}
        \mathcal{L}_{2\Phi} 
        = &- \sum_{a = 1}^3\big(m_{a}^2+Y_{a} \left(H^{\dagger}H\right)\big)\big(\Phi_a^{\dagger}\Phi_a\big)
        - \sum_{a = 1}^2 \big(m_{\tilde a}^2+Y_{\tilde a} \left(H^{\dagger}H\right) \big)\big(\Phi_{\tilde a}^{\dagger}\Phi_{\tilde a}\big) \\
&- Y_{22} \big(H^\intercal i\sigma_{2} \Phi_2\big)^\dagger \big(H^\intercal i\sigma_{2} \Phi_2\big)
        - Y_{\tilde{2}\tilde{2}} \big(H^\intercal i\sigma_{2} \Phi_{\tilde{2}} \big)^\dagger \big(H^\intercal i\sigma_{2} \Phi_{\tilde{2}} \big) \\
        &- iY_{33} \epsilon^{IJK} \left(H^\dagger \sigma^I H \right) \Phi_3^{J\dagger} \Phi_3^K\\
         \Big[&- A_{1\tilde{2}}\big( \Phi_{\tilde{2}}^\dagger H \big)\Phi_1 + A_{\tilde{2}3}\big(\Phi_{\tilde{2}}^\dagger \left(\sigma \cdot \Phi_3\right) H \big) + Y_{2\tilde{2}}\big(\Phi_{2}^\dagger H \big)\big(H^\intercal i\sigma_{2}\Phi_{\tilde{2}}\big)\\
        &+Y_{\tilde{1}3}\big(H^\intercal i\sigma_{2}\left(\sigma\cdot\Phi_{3}\right)^\dagger H\big)\Phi_{\tilde{1}} + Y_{13} \big(H^{\dagger}\left(\sigma\cdot\Phi_{3} \right)H \big)\Phi_{1}^{\dagger} + \text{h.c.}\Big] \,.
    \end{aligned}
    \label{eq:LQ_mixing}
\end{equation}


The color indices are omitted since they just involve trivial contractions. For example, the term with $Y_{22}$ in Eq.~(\ref{eq:LQ_mixing}) would be $- Y_{22} \left(H^\intercal i\sigma_{2} \Phi_{2, c_1} \right)^\dagger $ $ \left(H^\intercal i\sigma_{2} \Phi_{2, c_1} \right)$ in full notation. We use the convention that couplings with mass dimension one (zero) are denoted by $A$ ($Y$). \\

The terms in Eq.~(\ref{eq:LQ_mixing}) lead to mixing among the LQ eigenstates of the same electric charge after EW symmetry breaking. It is therefore convenient to collect them in the electric charge eigenstate vectors


\begin{equation}
    \begin{aligned}
        \Phi^{-1/3} &\equiv 
        \renewcommand{\arraystretch}{1.5}
                    \begin{pmatrix}
                        \Phi_1^{-1/3} \\ 
                        \Phi^{-1/3}_{\tilde{2}} \\
                        \Phi_3^{-1/3}
                    \end{pmatrix} \,, 
        &\Phi^{+2/3} &\equiv 
        \renewcommand{\arraystretch}{1.5}
                    \begin{pmatrix}
                        \Phi_2^{+2/3} \\ 
                        \Phi^{+2/3}_{\tilde{2}} \\
                        \Phi_3^{+2/3}
                    \end{pmatrix} \,, \\
        \Phi^{-4/3} &\equiv 
        \renewcommand{\arraystretch}{1.5}
                    \begin{pmatrix}
                        \Phi_{\tilde{1}}^{-4/3} \\ 
                        \Phi^{-4/3}_{3}
                    \end{pmatrix} \,,
       &\Phi^{+5/3} &\equiv 
       \renewcommand{\arraystretch}{1.5}
                    \begin{pmatrix}
                        \Phi_2^{+5/3}
                    \end{pmatrix}\,. 
    \end{aligned}
\label{eq:ChargeVectors}
\end{equation}


After spontaneous symmetry breaking, non-diagonal mass matrices $\mathbbm{M}^q$ in


\begin{equation}
    \mathcal{L}_{2\Phi} \supset - \sum_{q \in Q} \Phi^q{}^\dagger \mathbbm{M}^q \Phi^q
\end{equation} 


are generated with $Q = \left \{ -\frac{4}{3}, -\frac{1}{3}, +\frac{2}{3}, +\frac{5}{3} \right \}$ and~\cite{Crivellin:2020ukd, Hirsch:1996qy, AristizabalSierra:2007nf}


\begin{align}
    \begin{aligned}
        \mathbbm{M}^{-1/3} &=     \begin{pmatrix}
                                    			m_1^2 + \frac{v^2}{2} Y_1 & \frac{v}{\sqrt{2}} A_{1\tilde{2}}^*  & \frac{v^2}{2} Y_{13} \\ 
                                    			\frac{v}{\sqrt{2}} A_{1\tilde{2}} & m_{\tilde{2}}^2 + \frac{v^2}{2}Y_{\tilde{2}} & \frac{v}{\sqrt{2}} A_{\tilde{2}3} \\ 
                                    			\frac{v^2}{2} Y_{13}^* & \frac{v}{\sqrt{2}} A^*_{\tilde{2}3} & m_3^2 + \frac{v^2}{2} Y_3
                                			\end{pmatrix} \,, \\
        \mathbbm{M}^{+2/3} &=    \begin{pmatrix}
                                    			m_2^2 + \frac{v^2}{2} Y_2 & \frac{v^2}{2} Y_{2\tilde{2}} & 0 \\ 
                                    			\frac{v^2}{2} Y_{2\tilde{2}}^* & m_{\tilde{2}}^2 + \frac{v^2}{2} \left( Y_{\tilde{2}} + Y_{\tilde{2}\tilde{2}} \right) & -v A_{\tilde{2}3} \\ 
                                    			0 & - v A_{\tilde{2}3}^* & m_3^2 + \frac{v^2}{2} \left(Y_3 + Y_{33} \right)
                                			\end{pmatrix}  \,, \\
        \mathbbm{M}^{-4/3} &=    \begin{pmatrix}
                                   			m_{\tilde{1}}^2 + \frac{v^2}{2} Y_{\tilde{1}} & \frac{v^2}{\sqrt{2}}Y_{\tilde{1}3}^*\\ 
                                    			\frac{v^2}{\sqrt{2}} Y_{\tilde{1}3} & m_3^2 + \frac{v^2}{2}\left(Y_3 - Y_{33}\right) \\ 
                                			\end{pmatrix}   \,, \\
        \mathbbm{M}^{+5/3} &= m_2^2 + \frac{v^2}{2} \left(Y_2 + Y_{22} \right) \,.
    \end{aligned}
\end{align}


They can be diagonalized by rotating the LQs with unitary matrices


\begin{equation}
    W^q \Phi^q \equiv \hat{\Phi}^q \,,
\end{equation}


in order to arrive at the physical basis with digonal mass matrices. $W^q$ can be calculated perturbatively to arbitrary order in $v$~\cite{Crivellin:2020ukd, Rosiek:2015jua}. At $\mathcal{O}(v^2)$ one finds


\begin{align}
    \begin{aligned}
        W^{-1/3}& \approx \begin{pmatrix}
        1\!-\!\frac{v^2|A_{1\tilde 2}|^2}{4 (m_{1\tilde{2}}^2)^2}& \frac{v A_{1\tilde 2}^{*}}{\sqrt{2} m_{1\tilde{2}}^2} & \frac{v^2(Y_{13}m_{1 \tilde{2}}^2+A_{1\tilde 2}^{*}A_{\tilde 23})}{2 m_{13}^2 m_{1\tilde{2}}^2}\\
        \frac{-v A_{1\tilde 2}}{\sqrt{2} m_{1\tilde{2}}^2} & 1\!-\!\frac{v^2}{4}\left(\!\frac{|A_{1\tilde 2}|^2}{(m_{1\tilde{2}}^2 )^2}\!+\!\frac{|A_{\tilde 23}|^2}{(m_{3 \tilde{2}}^2)^2}\!\right)&
        \frac{-v A_{\tilde 23}}{\sqrt{2} m_{3\tilde{2}}^2}\\
        \frac{-v^2(Y_{13}^{*}(m_{3\tilde{2}}^2)+A_{1\tilde 2}A_{\tilde 23}^{*})}{2 m_{13}^2 m_{3\tilde{2}}^2}&\frac{v A_{\tilde 23}^{*}}{\sqrt{2} m_{3\tilde{2}}^2}& 1\!-\!\frac{v^2 |A_{\tilde 23}|^2}{4 (m_{3\tilde{2}}^2)^2}
        \end{pmatrix}\,,\\ \rule{0pt}{3em}
W^{+2/3}& \approx \begin{pmatrix}
        1& \frac{v^2 Y_{2\tilde 2}}{2 m_{2 \tilde{2}}^2} & 0\\
        \frac{-v^2 Y_{2\tilde 2}^{*}}{2 m_{2\tilde{2}}^2} & 1\!-\!\frac{v^{2}|A_{\tilde 23}|^2}{2 (m_{3 \tilde{2}}^2 )^2} & \frac{-vA_{\tilde 23}}{m_{\tilde{2}3}^2}\\
        0 & \frac{vA_{\tilde 23}^{*}}{m_{\tilde{2}3}^2} & 1-\frac{v^2|A_{\tilde 23}|^2}{2 (m_{3 \tilde{2}}^2 )^2 }
        \end{pmatrix}\,, \,W^{-4/3}\approx\begin{pmatrix}
        1 & \frac{v^2 Y_{\tilde 13}^{*}}{\sqrt{2}m_{\tilde{1}3}^2}\\
        \frac{-v^2 Y_{\tilde 13}}{\sqrt{2} m_{\tilde{1}3}^2}& 1
        \end{pmatrix}\,, \\
W^{+5/3} &= 1 \,,
    \end{aligned}
    \label{eq:Wmatrices}
\end{align}


where $m^2_{ab} \equiv m_a^2 - m_b^2$ for $a,b \in \left \{1, \tilde{1}, 2, \tilde{2}, 3 \right \}$. 

The diagonal mass matrices 


\begin{equation}
 \hat{\mathbbm{M}}^q \equiv W^q \mathbbm{M}^q \left( W^q \right)^\dagger 
\end{equation}


then read~\cite{Crivellin:2020ukd}


\begin{equation}
\begin{aligned}
\hat{\mathbbm{M}}^{-1/3}&\approx \text{diag}\Bigg(m_{1}^2+\frac{v^{2}}{2}\left(\!Y_{1}\!-\!\frac{|A_{1\tilde 2}|^2}{m_{\tilde{2}1}^2}\!\right) , \, m_{\tilde{2}}^2+\frac{v^{2}}{2}\left(\!Y_{\tilde{2}}\!+\!\frac{|A_{1\tilde 2}|^2}{m_{\tilde{2}1}^2}\!+\!\frac{|A_{\tilde 23}|^2}{m_{\tilde{2}3}^2}\!\right),\, \\ 
 & \phantom{\approx \text{diag}\Bigg(\,} m_{3}^2+\frac{v^{2}}{2}\left(\!Y_{3}\!-\!\frac{|A_{\tilde 23}|^2}{m_{\tilde{2}3}^2}\right)\Bigg)\,, \\
\hat{\mathbbm{M}}^{+2/3} &\approx \text{diag}\Bigg(m_{2}^2+\frac{v^{2}}{2}Y_{2} , \, m_{\tilde{2}}^2 +\frac{v^{2}}{2}\left(Y_{\tilde{2}}+\!Y_{\tilde{2}\tilde{2}}\!+\!\frac{2|A_{\tilde 23}|^2}{m_{\tilde{2}3}^2}\! \right),\, \\ 
 & \phantom{\approx \text{diag}\Bigg(\,} m_{3}^2+\frac{v^{2}}{2}\left(\!Y_{3} + Y_{33} \!-\!\frac{2|A_{\tilde 23}|^2}{m_{\tilde{2}3}^2}\!\right)
\Bigg)\,, \\
\hat{\mathbbm{M}}^{-4/3}&\approx \text{diag}\left(m_{\tilde{1}}^2+\frac{v^{2}}{2}Y_{\tilde{1}}, \, m_{3}^2+\frac{v^{2}}{2}\left(Y_{3} - Y_{33}\right)\right)\,, \\
\hat{\mathbbm{M}}^{+5/3}&=m_{2}^2+\frac{v^2}{2}\left(Y_{2}+Y_{22}\right)\,,
\end{aligned}
\label{eq:LQmassMatrices}
\end{equation}


up to order $v^2$. \\

The interactions of LQs with the Higgs field $h$ are determined by


\begin{align}
    \begin{aligned}
    \mathcal{L}_{2\Phi} &\supset \phantom{+} \sum_{q \in Q} \left( \Phi^{q\dagger} \mathbb{\Gamma}^q \Phi^q \right)h + \frac{1}{2} \sum_{q \in Q}  \left( \Phi^{q\dagger} \mathbb{\Lambda}^q \Phi^q \right)hh \\
    & = \phantom{+} \sum_{q \in Q} \left( \hat{\Phi}^{q\dagger} \hat{\mathbb{\Gamma}}^q \hat{\Phi}^q \right)h + \frac{1}{2} \sum_{q \in Q} \left( \hat{\Phi}^{q\dagger} \hat{\mathbb{\Lambda}}^q \hat{\Phi}^q \right)hh \,, \\
    \end{aligned}
\end{align}


with


\begin{equation*}
\begin{aligned}

        \mathbb{\Gamma}^{-1/3} &= 
                -v
                \begin{pmatrix}
                   Y_1  & \frac{A_{1\tilde{2}}^{*}}{\sqrt{2}v} & Y_{13}\\ 
                   \frac{A_{1\tilde{2}}}{\sqrt{2}v}  & Y_{\tilde{2}} & \frac{A_{\tilde{2}3}}{\sqrt{2}v}\\ 
                    Y_{13}^{*} & \frac{A^{*}_{\tilde{2}3}}{\sqrt{2}v} & Y_{3}
                \end{pmatrix}\,, 
         &\mathbb{\Gamma}^{+2/3} &= 
                \renewcommand{\arraystretch}{1.5}
                -v
                \begin{pmatrix}
                   Y_2  & Y_{2\tilde{2}} & 0\\ 
                  Y^{*}_{2\tilde{2}}  & Y_{\tilde{2}} + Y_{\tilde2 \tilde2} & -\frac{A_{23}}{v}\\ 
                    0 & -\frac{A^{*}_{23}}{v} & Y_3 + Y_{33}
                \end{pmatrix}\,, \\ \rule{0pt}{3em}
\end{aligned}
\end{equation*}
\begin{equation}
\begin{aligned}
        \mathbb{\Gamma}^{-4/3} &= 
                        \renewcommand{\arraystretch}{1.5}
                        -v
                        \begin{pmatrix}
                          Y_{\tilde{1}}  & \sqrt{2} Y^{*}_{\tilde{1}3} \\ 
                          \sqrt{2} Y_{\tilde{1}3}  & Y_3 - Y_{33} \\
                        \end{pmatrix}\,, 
        &\mathbb{\Gamma}^{+5/3} &= -v \Big(Y_2 + Y_{22} \Big) \,, \\
        \mathbb{\Lambda}^{-1/3} &= 
                -\phantom{v}\begin{pmatrix}
                   Y_1  & 0 & Y_{13}\\ 
                   0  & Y_{\tilde{2}} & 0\\ 
                    Y_{13}^{*} & 0 & Y_3
                \end{pmatrix} \,,
        &\mathbb{\Lambda}^{+2/3} &=
                -\phantom{v} \begin{pmatrix}
                   Y_2 & Y_{2\tilde{2}} & 0\\ 
                  Y^{*}_{2\tilde{2}}  & Y_{\tilde{2}} + Y_{\tilde2 \tilde2} & 0\\ 
                    0 & 0 & Y_3 + Y_{33}
                \end{pmatrix} \,, \\ \rule{0pt}{3em}
        \mathbb{\Lambda}^{-4/3} &=
                -\phantom{v}\begin{pmatrix}
                   Y_{\tilde{1}}  & \sqrt{2} Y^{*}_{\tilde{1}3} \\ 
                  \sqrt{2} Y_{\tilde{1}3}  & Y_3 - Y_{33} \\
                \end{pmatrix}\,, 
        &\mathbb{\Lambda}^{+5/3} &= -\phantom{v}\Big(Y_2 + Y_{22}\Big)\,, \\
    \end{aligned}
\end{equation}


and


\begin{align}
	\begin{aligned}
		\hat{\mathbb{\Gamma}}^q &= W^q \mathbb{\Gamma}^q \left(W^{q}\right)^\dagger \text{ for } q \in Q \,, \\
		\hat{\mathbb{\Lambda}}^q &= W^q \mathbb{\Lambda}^q \left(W^{q}\right)^\dagger \text{ for } q \in Q \,.
	\end{aligned}
\end{align} \\


The explicit expressions for these coupling matrices up to $\mathcal{O}(v^2)$ are given in Ref.~\cite{Crivellin:2020ukd}. \\

When listing the Feynman rules for interactions involving LQs of the same charge, we will have to relate the LQ label $a \in \left \{ 1, \tilde{1}, 2, \tilde{2}, 3 \right \}$ to the position in $\Phi^q$. For this we use the coefficients


\begin{equation}
    n_a^q \text{ with } q \in \left \{-\frac{4}{3},-\frac{1}{3}, +\frac{2}{3}, +\frac{5}{3} \right \} \text{ and } a \in \{1, \tilde{1}, 2, \tilde{2}, 3 \}.
    \label{eq:nqi}
\end{equation}


Explicitly, we have


\renewcommand{\arraystretch}{1.5}
\begin{center}
    \begin{tabular}{ r|c c c c c c|}
     $n_a^q$ & $a = 1$ & $a = \tilde{1}$ & $a = 2$ & $a = \tilde{2}$ & $a = 3$ \\
    \hline
       $q = -\frac{1}{3}$ & 1 & 0 & 0 & 2 & 3 \\
       $q = +\frac{2}{3}$ & 0 & 0 & 1 & 2 & 3 \\
       $q = -\frac{4}{3}$ & 0 & 1 & 0 & 0 & 2 \\
       $q = +\frac{5}{3}$ & 0 & 0 & 1 & 0 & 0 \\
    \end{tabular}\,.
\end{center}


Whenever $q$ is clear from the context, we write $n^q_a$ as $n_a$ to simplify the notation. 



\subsection{Kinetic Terms and Interactions with SM Gauge Bosons ($\mathcal{L}_{\text{kin}}$)}
\label{sec:LQkin}
The kinetic terms for the LQs as well as their couplings to the SM gauge bosons are presented in this section. The same conventions as for the SM are used. For the three-dimensional adjoint representation of $SU(2)_L$, the $I^{\text{th}}$ generator ($I \in \{1,2,3\}$) has the $3\times3$ matrix form  $(\tilde{\epsilon}_I)_{JK} \equiv i \epsilon_{IJK}$, where $\epsilon_{IJK}$ is the three-dimensional Levi-Civita tensor.  We use the convention $\epsilon_{123} = +1$.


\begin{equation}
    \renewcommand{\arraystretch}{1.5}
    \centering
    \begin{tabular}{c | c c}
          & $\mathcal{L}_{\text{kin}}$ & $D_\mu$ \\ \hline \rule{0pt}{2em}

    	$\Phi_1$ &  $\left(\left( D_\mu \Phi_1 \right)^{\dagger}D^\mu \Phi_1 \right)$ & $ \partial_\mu + \frac{i}{3}g_1 B_\mu - i g_s \frac{\lambda_\alpha}{2} G^\alpha_\mu$\\ \rule{0pt}{2em}

    	$\Phi_{\tilde{1}}$ & $\left(\left( D_\mu \Phi_{\tilde{1}} \right)^{\dagger}D^\mu \Phi_{\tilde{1}} \right)$ & $ \partial_\mu + \frac{4i}{3}g_1  B_\mu - i g_s \frac{\lambda_\alpha}{2} G^\alpha_\mu $\\ \rule{0pt}{2em}

    	$\Phi_{2}$ &  $\left(\left( D_\mu \Phi_{2} \right)^{\dagger}D^\mu \Phi_{2} \right)$ & $ \partial_\mu - \frac{7i}{6}g_1 B_\mu - i g_2 \frac{\sigma_I}{2} W_\mu^{I} - i g_s \frac{\lambda_\alpha}{2} G^\alpha_\mu $\\ \rule{0pt}{2em}

    	$\Phi_{\tilde{2}}$  & $\left(\left( D_\mu \Phi_{\tilde{2}} \right)^{\dagger}D^\mu \Phi_{\tilde{2}}\right)$ & $ \partial_\mu - \frac{i}{6}g_1 B_\mu - i g_2 \frac{\sigma_I}{2} W_\mu^{I} - i g_s \frac{\lambda_\alpha}{2} G^\alpha_\mu$\\ \rule{0pt}{2em}

    	$\Phi_{3}$ &  $\left(\left( D_\mu \Phi_{3} \right)^{\dagger}D^\mu \Phi_{3}\right)$ & $ \partial_\mu + \frac{i}{3}g_1 B_\mu - i g_2 \tilde{\epsilon}_I W_\mu^{I} - i g_s \frac{\lambda_\alpha}{2} G^\alpha_\mu$\\
    \end{tabular}
\end{equation}


By definition, the $\Phi^q$ couple to the photon with the electric charge $q$. The couplings to the electroweak SM gauge bosons are given by 


\begin{align}
    \begin{aligned}
        \mathcal{L}_\text{kin} &\supset \phantom{+} i\dfrac{e}{s_w c_w} \sum_{q \in Q}\left(\Phi^{q\dagger}\mathbbm{Z}^{q} \overset{\leftrightarrow}{\partial^\mu} \Phi^{q} \right) Z_{\mu} \\ 
        &\phantom{12}+ i\dfrac{e}{s_w} \sum_{q \in Q\backslash \left\{+\frac{5}{3}\right\}} \left( \left(\Phi^{q+1}\right)^\dagger \mathbbm{W}_{q}^{q+1} \overset{\leftrightarrow}{\partial^\mu} \Phi^q\right)W^+_\mu \,,
    \end{aligned}
\end{align}


where $\Phi^\dagger \overset{\leftrightarrow}{\partial^\mu} \Phi \equiv \Phi^\dagger \partial^\mu \Phi - \left(\partial^\mu \Phi^\dagger\right) \Phi$, $Q = \left\{ -\frac{4}{3}, -\frac{1}{3}, +\frac{2}{3}, +\frac{5}{3} \right\}$ and


\begin{equation*}
    \begin{aligned}
        \mathbbm{Z}^{-1/3} &= 
                \renewcommand{\arraystretch}{1.0}
                \begin{pmatrix}
                    \dfrac{1}{3}s_w^2 & 0 & 0 \\ 
                    0 & -\dfrac{1}{2} + \dfrac{1}{3}s_w^2 & 0\\ 
                    0 & 0 & \dfrac{1}{3}s_w^2
                \end{pmatrix} \,,
        &\mathbbm{Z}^{-4/3} &= 
                        \renewcommand{\arraystretch}{1.0}
                        \begin{pmatrix}
                            \dfrac{4}{3}s_w^2 & 0\\ 
                            0 & -1 + \dfrac{4}{3}s_w^2
                        \end{pmatrix} \,, \\
        \mathbbm{Z}^{+2/3} &= 
                \renewcommand{\arraystretch}{1.0}
                \begin{pmatrix}
                    -\dfrac{1}{2} - \dfrac{2}{3}s_w^2 & 0 & 0 \\
                    0 & \dfrac{1}{2} - \dfrac{2}{3}s_w^2 & 0\\ 0 & 0 & 1 - \dfrac{2}{3}s_w^2
                \end{pmatrix} \,,
        &\mathbbm{Z}^{+5/3} &= 
                        \left(\dfrac{1}{2} - \dfrac{5}{3} s_w^2\right)\,,
  \end{aligned}
\end{equation*}
\begin{equation}
  \begin{aligned}
        \mathbbm{W}^{+2/3}_{-1/3} &=
                \renewcommand{\arraystretch}{1.0}
                \begin{pmatrix}
                    0 & 0 & 0 \\ 
                    0 & 1 & 0\\ 
                    0 & 0 & - \sqrt{2}
                \end{pmatrix} \,, &
        \mathbbm{W}^{-1/3}_{-4/3} &=
                \renewcommand{\arraystretch}{1.0}
                \begin{pmatrix}
                    0 & 0  \\ 
                    0 & 0 \\
                    0 & \sqrt{2}
                \end{pmatrix} \,, &
        \mathbbm{W}^{+5/3}_{+2/3} &= 
                \renewcommand{\arraystretch}{1.0}
                \begin{pmatrix}
                   1 & 0 & 0 \\
                \end{pmatrix} \,.
    \end{aligned}
    \label{eq:LQchargeMatrices}
\end{equation}


Such interactions were first considered in Ref.~\cite{Blumlein:1992ej}. Expressed in the mass basis for the LQs, they take the form


\begin{align}
    \begin{aligned}
        \mathcal{L}_\text{kin} &\supset +i\dfrac{e}{s_w c_w} \sum_{q \in Q}\left(\hat{\Phi}^{q\dagger}\hat{\mathbbm{Z}}^{q} \overset{\leftrightarrow}{\partial^\mu} \hat{\Phi}^{q} \right) Z_{\mu} \\ 
        &\phantom{12}+ i\dfrac{e}{s_w} \sum_{q \in Q\backslash\{+\frac{5}{3}\}} \left( \left(\hat{\Phi}^{q+1}\right)^\dagger \hat{\mathbbm{W}}_{q}^{q+1} \overset{\leftrightarrow}{\partial^\mu} \hat{\Phi}^q\right)W^+_\mu \,.
    \end{aligned}
\end{align}


with


\begin{align}
	\begin{aligned}
		\hat{\mathbbm{Z}}^q &\equiv W^q \mathbbm{Z}^q \left(W^{q}\right)^\dagger \text{ for } q \in Q \,, \\
		\hat{\mathbbm{W}}_q^{q+1} &\equiv W^{q+1} \mathbbm{W}_q^{q+1} \left(W^{q}\right)^\dagger \text{ for } q \in Q \backslash \left \{ +\frac{5}{3} \right \}\,. \\
	\end{aligned}
\end{align}


Explicitly, the matrices $\hat{\mathbbm{Z}}^q, \hat{\mathbbm{W}}_q^{q+1}$ are given by


\begin{align}
