        -\frac{v^2 A_{1\tilde{2}} A_{\tilde{2}3}^*}{4 m_{1 \tilde{2}}^2  m_{3\tilde{2}}^2} & - \frac{v A_{\tilde{2}3}^*}{2 \sqrt{2} m_{3 \tilde{2}}^2}& \frac{1}{3}s_w^2 - \frac{v^2 \left| A_{\tilde{2}3} \right|^2}{4 \left(m_{3 \tilde{2}}^2 \right)^2} \\
        \end{pmatrix}\,,\\ \rule{0pt}{3em}
