        -\frac{1}{2} - \frac{2}{3}s_w^2 & \frac{v^2Y_{2\tilde{2}}}{2 m_{2 \tilde{2}}^2} & 0 \\
        \frac{v^2Y^*_{2\tilde{2}}}{2 m_{2 \tilde{2}}^2} & \frac{1}{2}-\frac{2}{3}s_w^2 + \frac{ v^2 \left| A_{\tilde{2}3}\right|^2}{2\left(m_{\tilde{2}3}^2\right)^2} & -\frac{v A_{\tilde{2}3}}{2 m_{\tilde{2}3}^2} \\
        0 & -\frac{v A_{\tilde{2}3}^*}{2 m_{\tilde{2}3}^2} & 1 - \frac{2}{3} s_w^2 -  \frac{v^2 \left| A_{\tilde{2}3}\right|^2}{2 \left(m_{\tilde{2}3}^2 \right)^2} \\
        \end{pmatrix}\,, \\ \rule{0pt}{1em}
        \hat{\mathbbm{Z}}^{-4/3}&\approx\begin{pmatrix}
        \frac{4}{3}s_w^2 & -\frac{v^2 Y_{\tilde{1}3}^*}{\sqrt{2} m_{\tilde{1}3}^2}\\
        -\frac{v^2 Y_{\tilde{1}3}}{\sqrt{2}m_{\tilde{1}3}^2} & -1 + \frac{4}{3}s_w^2\\
        \end{pmatrix}\,, ~\hat{\mathbbm{Z}}^{+5/3} = \left(\frac{1}{2} - \frac{5}{3}s_w^2 \right)\,, \\
        \hat{\mathbbm{W}}^{+2/3}_{-1/3}& \approx \renewcommand*{\arraystretch}{2.0}  \begin{pmatrix}
