\subsection{Interactions with SM Fermions ($\mathcal{L}_{\text{f}}$)}
The interactions between the five scalar LQs and the SM fermions are listed below. $Y_{a}^{AB}{}$ with $a \in \{1, \tilde1, 2, \tilde2, 3 \}$ and $A,B \in \{L, R\}$ are arbitrary complex $3 \times 3$ matrices coupling LQs to a quark and a lepton. $Y_a^{Q,AA}$ with $a \in \left \{ 1, \tilde{1}, 2, \tilde{2}, 3 \right \}$ and $A \in \left \{ L, R\right \}$ couple LQs to two quarks. $Y_1^{Q, LL}$ is symmetric in flavour space (i.e. $Y_{1, ij}^{Q, LL}$ = $Y_{1, ji}^{Q, LL}$ ), $Y_{\tilde{1}}^{Q, RR}$ and $Y_{3}^{Q, LL}$ are anti-symmetric and $Y_{1}^{Q, RR}$ is again an arbitrary complex matrix. We omit the color indices whenever they just involve trivial contractions. 


\begin{equation}
    \renewcommand{\arraystretch}{1.5}
    \centering
    \begin{tabular}{c | c} 
         & $\mathcal{L}_{f}$ \\ \hline \rule{0pt}{2em}

    	\multirow{3}{*}{$\Phi_1$} & $Y_{1, ij}^{RR}\, \bar{u}^{\prime c}_i\ell^\prime_{j}\Phi_{1}^{\dagger} +Y_{1, ij}^{LL}\, \left(\bar{Q}_{i}^{\prime c \intercal} i\sigma_{2}L^\prime_{j}\right)\Phi_{1}^{\dagger}+\text{h.c.}$ \\ 
	\multirow{3}{*} &  $Y_{1, ij}^{Q, LL}\, \left(\bar{Q}^{\prime c \intercal}_{i, c_1} i\sigma_2 Q^\prime_{j, c_2}\right) \Phi_{1, c_3} \epsilon^{c_1 c_2 c_3} +\text{h.c.}$ \\ 
	\multirow{3}{*} &  $Y_{1, ij}^{Q, RR} \bar{u}^{\prime c}_{i, c1} d^\prime_{j, c_2} \Phi_{1, c_3} \epsilon^{c_1 c_2 c_3} +\text{h.c.}$ \\ \rule{0pt}{2em}

    	\multirow{2}{*}{$\Phi_{\tilde{1}}$} & $Y^{RR}_{\tilde{1}, ij}\, \bar{d}^{\prime c}_{i}\ell^\prime_{j}\Phi_{\tilde{1}}^{\dagger} +\text{h.c.}$ \\
	\multirow{2}{*} & $Y^{Q, RR}_{\tilde{1}, ij}\, \bar{u}^{\prime c}_{i, c_1} u^\prime_{j, c_2}\Phi_{\tilde{1}, c_3} \epsilon^{c_1 c_2 c_3} +\text{h.c.}$ \\ \rule{0pt}{2em}

    	$\Phi_{2}$  & $Y_{2, ij}^{RL}\, \left(\Phi_{2}^\intercal \bar{u}^\prime_i i\sigma_2 L^\prime_{j} \right)+Y_{2, ij}^{LR}\, \left(\bar{Q}^{\prime \intercal}_i \ell^\prime_j\Phi_{2}\right)+\text{h.c.}$\\ \rule{0pt}{2em}

    	$\Phi_{\tilde{2}}$ & $Y_{\tilde{2}, ij}^{RL}\, \left(\Phi_{\tilde{2}}^\intercal \bar{d}^\prime_{i} i\sigma_2 L^\prime_{j}\right)+\text{h.c.}$ \\ \rule{0pt}{2em}

	\multirow{2}{*}{$\Phi_{3}$}  & $Y_{3, ij}^{LL}\, \left(\bar{Q}^{\prime c \intercal}_{i} i\sigma_{2}\left(\sigma\cdot\Phi_{3}\right)^{\dagger}L^\prime_{j}\right)+\text{h.c.}$ \\
	\multirow{2}{*} &  $Y^{Q, LL}_{3, ij}\, \left(\bar{Q}^{\prime c \intercal}_{i, c_1} i\sigma_2 \left(\sigma \cdot \Phi_{3, c_3}\right)Q^\prime_{j, c_2}\right) \epsilon^{c_1 c_2 c_3} +\text{h.c.}$ \\
    \end{tabular}
    \label{eq:LQ_yukawa}
\end{equation}


Again, we use brackets to indicate the $SU(2)_L$ contractions. Note that we stated the Lagrangian above before EW symmetry breaking using the weak eigenstates of the fermions (indicated by the prime). When going to the mass eigenbasis (after EW symmetry breaking), CKM matrix elements enter interactions involving left-handed down-type quarks according to Eq.~(\ref{eq:massEigenstates}). 







The charge-conjugate of a fermion field $\Psi$ is denoted as $\Psi^c$, where
\begin{equation}
\begin{aligned}
	\Psi^c &= C \bar{\Psi}^\intercal \,, \\
	\bar{\Psi}^c &= - \Psi^\intercal C^{-1}\,,
\end{aligned}
\label{eq:Cmatrix}
\end{equation}


with $C$ the charge conjugation matrix. A detailed description of our treatment of charge-conjugate SM fermions is given in \ref{sec:appendix}. 



