3 \otimes \overline{3} \otimes 3 \otimes \overline{3} = 1 \oplus 1 \oplus 8 \oplus 8 \oplus 8 \oplus 8 \oplus 10 \oplus \overline{10} \oplus 27
\label{eq:SU(3)_singlets}
\end{equation}
is the only tensor product of four $SU(3)_{c}$ fundamental representations $\left(3, \overline{3}\right)$ that contains a singlet. Trivial combinations of LQ fields that contribute to the four-LQ Lagrangian are of the type
