        &+ \frac{1}{2} Y^{(5)}_{3} \left( \Phi_{3, c_1}^{I\dagger} \Phi_{3, c_1}^{J}  \Phi_{3, c_2}^{I\dagger} \Phi_{3, c_2}^{J}\right) \\
        	&+\sum_{a \neq b} \left( Y^{(1)}_{ab} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^{\prime(1)}_{ab} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right)  \left( \Phi_{a, c_1}^\dagger \Phi_{a, c_2}\right) \left( \Phi_{b, c_3}^\dagger \Phi_{b, c_4} \right) \\
         &+\left( Y^{(3)}_{2\tilde{2}} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^{\prime(3)}_{2\tilde{2}} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right)  \left( \Phi_{2, c_1}^\dagger \Phi_{\tilde{2}, c_2}\right) \left( \Phi_{\tilde{2}, c_3}^\dagger \Phi_{2, c_4} \right) \\
      \end{aligned}
\end{align*}
\begin{align}
	\begin{aligned}
        &+ \sum_{a = 2, \tilde{2}}\left( Y^{(3)}_{a3} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^{\prime(3)}_{a3} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right)\left(\Phi_{a, c_1}^\dagger \sigma^I \Phi_{a, c_2} \right)\left(\Phi_{3, c_3}^{J\dagger} i\epsilon^{IJK} \Phi_{3, c_4}^K \right) \\
        &+ \Bigg[ \phantom{+} \sum_{a =   2, \tilde{2} } \left(Y_{1aa3} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^\prime_{1aa3} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right) \Phi^\dagger_{1, c_1}  \left(\Phi_{a, c_3}^\dagger \big(\sigma \cdot \Phi_{3, c_4} \big) \Phi_{a, c_2} \right)  \\
        &\phantom{12 +\Bigg[}+ \left(Y_{\tilde{1} \tilde{2} 2 3}\  \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^\prime_{\tilde{1} \tilde{2} 2 3} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right) \Phi_{\tilde{1}, c_1}^\dagger  \left(\Phi_{2, c_3}^\dagger \big(\sigma \cdot \Phi_{3, c_4} \big)\Phi_{\tilde{2}, c_2} \right) \\
         &\phantom{12 + \Bigg[}+ \left(Y_{1 \tilde{1} \tilde{2} 2} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^\prime_{1 \tilde{1} \tilde{2} 2}\  \delta_{c_1 c_4} \delta_{c_2 c_3} \right) \Phi^\dagger_{1, c_1} \Phi_{\tilde{1}, c_2} \big(\Phi_{\tilde{2}, c_3}^\dagger  \Phi_{2, c_4}\big) \\
         &\phantom{12 + \Bigg[}+ \frac{1}{2} Y_{1 3 1 3} \ \delta_{c_1 c_2} \delta_{c_3 c_4} \left(\Phi^\dagger_{1, c_1} \Phi^I_{3, c_2} \Phi^\dagger_{1, c_3} \Phi^I_{3, c_4} \right) \\
         &\phantom{12 + \Bigg[}+ Y_{1 3 3 3} \ \delta_{c_1 c_2} \delta_{c_3 c_4} \left(\Phi^\dagger_{1, c_1} \Phi^I_{3, c_2} \Phi^{J \dagger}_{3, c_3} \Phi^K_{3, c_4} i\epsilon^{IJK} \right) \text{~ + h.c.} \Bigg]\,,
        \label{eq:LQ_quartic_interactions}
    \end{aligned}
\end{align}


with $a, b \in \left \{1, \tilde{1}, 2, \tilde{2}, 3 \right \}$ unless stated otherwise. Note that we set $Y^{(1)}_{ab} = Y^{(1)}_{ba}$ and $Y^{(1)\prime}_{ab} = Y^{(1)\prime}_{ba}$ for $a \neq b$, since they correspond to the same terms. The Feynman rules are expressed using only one of them, i.e. $Y^{(1)}_{\tilde{1}3}$, but not $Y^{(1)}_{3\tilde{1}}$.  









